--[=[
    @class IServiceScope
    服务作用域
]=]

export type IServiceScope = {
    --- 释放作用域
    Dispose: (self: IServiceScope) -> (),

    --- 获取服务
    GetService: (self: IServiceScope, serviceType: string) -> any?,

    --- 获取必需服务
    GetRequiredService: (self: IServiceScope, service: string) -> any,

    --- 获取服务提供者
    GetServiceProvider: (self: IServiceScope) -> IServiceProvider
}

return {}